def nm(r, c):
    return 'R%dC%d' % (r + 1, c + 1)

def add(out, cells, chk, txt):
    out.append({'cells': cells, 'check': chk, 'text': txt})

def clues(sol):
    out = []
    R = len(sol)
    C = len(sol[0])
    for r in range(R):
        for c in range(C):
            v = sol[r][c]
            add(out, [(r, c)], 'lambda a: a == %d' % v, '%s = %d' % (nm(r, c), v))
            for dr, dc in ((0, 1), (1, 0)):
                r2 = r + dr
                c2 = c + dc
                if r2 >= R or c2 >= C:
                    continue
                a = v
                b = sol[r2][c2]
                cl = [(r, c), (r2, c2)]
                n1 = nm(r, c)
                n2 = nm(r2, c2)
                if (a + b) % 2 == 0:
                    add(out, cl, 'lambda a, b: (a + b) % 2 == 0', '%s and %s have the same parity' % (n1, n2))
                else:
                    add(out, cl, 'lambda a, b: (a + b) % 2 == 1', '%s and %s have different parity' % (n1, n2))
                if abs(a - b) == 1:
                    add(out, cl, 'lambda a, b: abs(a - b) == 1', '%s and %s differ by exactly 1' % (n1, n2))
                elif abs(a - b) >= 3:
                    add(out, cl, 'lambda a, b: abs(a - b) >= 3', '%s and %s differ by at least 3' % (n1, n2))
                if a != b and (a % b == 0 or b % a == 0):
                    add(out, cl, 'lambda a, b: a % b == 0 or b % a == 0', 'One of %s, %s divides the other' % (n1, n2))
                if a + b in (3, 5, 7):
                    add(out, cl, 'lambda a, b: a + b == 3 or a + b == 5 or a + b == 7', 'Sum of %s and %s is prime' % (n1, n2))
                else:
                    add(out, cl, 'lambda a, b: a + b == 4 or a + b == 6 or a + b == 8 or a + b == 9', 'Sum of %s and %s is not prime' % (n1, n2))
    return out

