def clues(sol):
    out = []
    R = len(sol)
    C = len(sol[0])
    names = ['a', 'b', 'c', 'd']
    head = 'lambda a, b, c, d: '
    for r in range(R):
        for c in range(C):
            v = sol[r][c]
            add(out, [(r, c)], 'lambda a: a == %d' % v, '%s = %d' % (nm(r, c), v))
    for r in range(R - 1):
        for c in range(C - 1):
            cl = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            vals = [sol[x][y] for (x, y) in cl]
            w = nm(r, c)
            s = sum(vals)
            add(out, cl, head + 'a + b + c + d == %d' % s, 'Window at %s has sum %d' % (w, s))
            if s % 2 == 0:
                add(out, cl, head + '(a + b + c + d) % 2 == 0', 'Window at %s has an even sum' % w)
            else:
                add(out, cl, head + '(a + b + c + d) % 2 == 1', 'Window at %s has an odd sum' % w)
            m = max(vals)
            if vals.count(m) == 1:
                i = vals.index(m)
                chk = head + ' and '.join('%s > %s' % (names[i], names[j]) for j in range(4) if j != i)
                add(out, cl, chk, '%s is the strict maximum of the window at %s' % (nm(cl[i][0], cl[i][1]), w))
            m = min(vals)
            if vals.count(m) == 1:
                i = vals.index(m)
                chk = head + ' and '.join('%s < %s' % (names[i], names[j]) for j in range(4) if j != i)
                add(out, cl, chk, '%s is the strict minimum of the window at %s' % (nm(cl[i][0], cl[i][1]), w))
            if vals[0] == vals[3]:
                add(out, cl, head + 'a == d', 'Main diagonal of the window at %s is equal' % w)
            if vals[1] == vals[2]:
                add(out, cl, head + 'b == c', 'Anti-diagonal of the window at %s is equal' % w)
    return out

